/* From Uiverse.io by Yaya12085 - Tags: form */
.__UIV_SCOPE__ .modal {
  background-color: rgb(255, 255, 255);
  border-radius: 1em;
  box-shadow: 0px 100px 48px -60px rgba(0,0,0,0.1);
  color: rgb(15, 14, 14);
  max-width: 330px;
  overflow: hidden;
  position: relative;
  transition: background-color 0.3s, color 0.3s;
}

.__UIV_SCOPE__ .content > *, .__UIV_SCOPE__ .modal > * {
  padding: 0.875em;
}

.__UIV_SCOPE__ .title {
  font-size: 1.25em;
  font-weight: 600;
  line-height: 1.2;
  display: flex;
  justify-content: center;
}

.__UIV_SCOPE__ .message {
  line-height: 1.2;
  text-align: center;
}

.__UIV_SCOPE__ .actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.__UIV_SCOPE__ .upload-btn {
  background-color: transparent;
  border: 0.125rem dashed hsla(223,10%,50%,0.4);
  flex: 1;
  padding: 0.375rem 2rem;
}

.__UIV_SCOPE__ .upload-btn:hover {
  background-color: hsla(223,10%,60%,0.2);
}

.__UIV_SCOPE__ .close {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgb(226, 94, 54);
  height: 30px;
  width: 30px;
  border-radius: 50%;
  position: absolute;
  right: 10px;
  top: 10px;
  color: #fff;
  font-weight: bold;
  cursor: pointer;
}

.__UIV_SCOPE__ .result {
  margin-top: 4px;
  background-color: rgba(0, 140, 255, 0.062);
  display: flex;
  align-items: center;
  position: relative;
  border-radius: 1em;
}

.__UIV_SCOPE__ .file-uploaded {
  font-weight: 300;
}

.__UIV_SCOPE__ .file-uploaded::before {
  position: absolute;
  content: "X";
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgba(26, 7, 1, 0.212);
  height: 30px;
  width: 30px;
  border-radius: 50%;
  right: 10px;
  top: 10px;
  color: rgb(255, 255, 255);
  font-weight: bold;
  cursor: pointer;
}

.__UIV_SCOPE__ .file-uploaded:hover::before {
  background-color: rgba(233, 40, 6, 0.664);
}
